  `);g.transaction(()=>{for(let n of oO)r.run(n.key,n.name,n.description,n.tier,n.discountPct,JSON.stringify(n.itemKeys),n.vendorItemKeys?JSON.stringify(n.vendorItemKeys):null,n.sortOrder)})()}function bne(){g.prepare("INSERT INTO repair_incentive_settings (id) VALUES (1) ON CONFLICT(id) DO NOTHING").run()}function Ene(){g.prepare("INSERT INTO land_clearing_settings (id) VALUES (1) ON CONFLICT(id) DO NOTHING").run(),g.prepare("INSERT INTO vendor_quote_settings (id) VALUES (1) ON CONFLICT(id) DO NOTHING").run()}function wne(r,t){let n=Math.max(0,Number(r)||0),e=n<t.acreage_threshold?t.base_price:Math.round(n*t.per_acre_rate*100)/100,o=Math.round(e*(1+t.markup_pct)*100)/100;return{acres:n,vendorCost:e,clientPrice:o,markupPct:t.markup_pct}}function Tne(){let r=g.prepare(`
